def lis(arr):
    ends = {}
    longest = 0

    for i, val in enumerate(arr):
        # Find the longest prefix length where the tail value is less than val
        prefix_lengths = [j for j in range(1, longest + 1) if arr[ends[j]] < val]
        length = max(prefix_lengths) if prefix_lengths else 0

        # Update the end index for the current length
        if length == longest or (length < longest and val < arr[ends[length + 1]]):
            ends[length + 1] = i
            if length == longest:
                longest = length + 1

    return longest


print(lis([]))
print(lis([3]))
print(lis([10, 20, 11, 32, 22, 48, 43]))
